1	package main
2	
3	import (
4		"context"
5		"errors"
6		"fmt"
7		"io"
8		"strconv"
9		"strings"
10	
11		"github.com/entireio/cli/cmd/entire/cli/checkpoint"
12		checkpointID "github.com/entireio/cli/cmd/entire/cli/checkpoint/id"
13		"github.com/entireio/cli/cmd/entire/cli/paths"
14		"github.com/entireio/cli/cmd/entire/cli/session"
15		"github.com/entireio/cli/redact"
16	
17		"github.com/go-git/go-git/v6"
18		"github.com/go-git/go-git/v6/plumbing/object"
19	)
20	
21	type migrationOptions struct {
22		apply bool
23	}
24	
25	type migrationReport struct {
26		DiscoveredCheckpoints       int
27		ExistingV1Sessions          int
28		MissingV2CheckpointMetadata int
29		MissingV2SessionMetadata    int
30		MissingRawTranscripts       int
31		EligibleCheckpoints         int
32		V2OrphanCheckpoints         int
33		EligibleSessions            int
34		MigratedCheckpoints         int
35		MigratedSessions            int
36		Candidates                  []migrationCandidate
37	}
38	
39	type migrationCandidate struct {
40		CheckpointID string
41		SessionCount int
42		CommitSHAs   []string
43	}
44	
45	type checkpointMigrator struct {
46		repo        *git.Repository
47		v1Store     *checkpoint.GitStore
48		v2Store     *checkpoint.V2GitStore
49		authorIndex *v2SessionAuthorIndex
50		opts        migrationOptions
51		report      *migrationReport
52	}
53	
54	func migrateDiscoveredCheckpoints(ctx context.Context, repo *git.Repository, discovered []discoveredCheckpoint, opts migrationOptions) (migrationReport, error) {
55		v2Store := checkpoint.NewV2GitStore(repo)
56		report := migrationReport{DiscoveredCheckpoints: len(discovered)}
57		migrator := checkpointMigrator{
58			repo:    repo,
59			v1Store: checkpoint.NewGitStore(repo),
60			v2Store: v2Store,
61			opts:    opts,
62			report:  &report,
63		}
64	
65		for _, discoveredCheckpoint := range discovered {
66			eligibleSessions, err := migrator.migrateCheckpoint(ctx, discoveredCheckpoint)
67			if err != nil {
68				return report, err
69			}
70			if eligibleSessions == 0 {
71				continue
72			}
73			report.EligibleCheckpoints++
74			if len(discoveredCheckpoint.Commits) == 0 {
75				report.V2OrphanCheckpoints++
76			}
77			report.Candidates = append(report.Candidates, migrationCandidateFromDiscovered(discoveredCheckpoint, eligibleSessions))
78			if opts.apply {
79				report.MigratedCheckpoints++
80			}
81		}
82		return report, nil
83	}
84	
85	func migrationCandidateFromDiscovered(discovered discoveredCheckpoint, sessionCount int) migrationCandidate {
86		commitSHAs := make([]string, len(discovered.Commits))
87		for i, commit := range discovered.Commits {
88			commitSHAs[i] = commit.ShortSHA
89		}
90		return migrationCandidate{
91			CheckpointID: discovered.ID.String(),
92			SessionCount: sessionCount,
93			CommitSHAs:   commitSHAs,
94		}
95	}
96	
97	func (m *checkpointMigrator) migrateCheckpoint(ctx context.Context, discovered discoveredCheckpoint) (int, error) {
98		existing, err := m.v1Store.ReadCommitted(ctx, discovered.ID)
99		if err != nil {
100			return 0, fmt.Errorf("read v1 checkpoint %s: %w", discovered.ID, err)
101		}
102		existingSessionIDs, err := m.existingV1SessionIDs(ctx, discovered, existing)
103		if err != nil {
104			return 0, err
105		}
106	
107		summary, err := m.v2Store.ReadCommitted(ctx, discovered.ID)
108		if err != nil {
109			return 0, fmt.Errorf("read v2 checkpoint %s: %w", discovered.ID, err)
110		}
111		if summary == nil || len(summary.Sessions) == 0 {
112			m.report.MissingV2CheckpointMetadata++
113			return 0, nil
114		}
115	
116		eligibleSessions := 0
117		canPreserveCombinedAttribution := true
118		var eligible []eligibleV2Session
119		for sessionIndex := range summary.Sessions {
120			metadataContent, err := m.v2Store.ReadSessionMetadataAndPrompts(ctx, discovered.ID, sessionIndex)
121			if err != nil {
122				if errors.Is(err, checkpoint.ErrCheckpointNotFound) {
123					m.report.MissingV2SessionMetadata++
124					canPreserveCombinedAttribution = false
125					continue
126				}
127				return eligibleSessions, fmt.Errorf("read v2 checkpoint %s session %d metadata: %w", discovered.ID, sessionIndex, err)
128			}
129			if !hasRequiredV2Metadata(metadataContent) {
130				m.report.MissingV2SessionMetadata++
131				canPreserveCombinedAttribution = false
132				continue
133			}
134			if _, exists := existingSessionIDs[metadataContent.Metadata.SessionID]; exists {
135				m.report.ExistingV1Sessions++
136				continue
137			}
138	
139			content, err := m.v2Store.ReadSessionContent(ctx, discovered.ID, sessionIndex)
140			if err != nil {
141				if errors.Is(err, checkpoint.ErrNoTranscript) {
142					m.report.MissingRawTranscripts++
143					canPreserveCombinedAttribution = false
144					continue
145				}
146				return eligibleSessions, fmt.Errorf("read v2 checkpoint %s session %d: %w", discovered.ID, sessionIndex, err)
147			}
148	
149			m.report.EligibleSessions++
150			eligible = append(eligible, eligibleV2Session{sessionIndex: sessionIndex, content: content})
151			eligibleSessions++
152		}
153	
154		if m.opts.apply {
155			combinedAttribution := summary.CombinedAttribution
156			if !canPreserveCombinedAttribution {
157				combinedAttribution = nil
158			}
159			for _, entry := range eligible {
160				author, err := m.findV2SessionAuthor(ctx, discovered.ID, entry.sessionIndex)
161				if err != nil {
