1	package main
2	
3	import (
4		"context"
5		"errors"
6		"fmt"
7		"io"
8		"sort"
9		"strings"
10		"time"
11	
12		"github.com/entireio/cli/cmd/entire/cli/checkpoint"
13		checkpointID "github.com/entireio/cli/cmd/entire/cli/checkpoint/id"
14		"github.com/entireio/cli/cmd/entire/cli/paths"
15		"github.com/entireio/cli/cmd/entire/cli/trailers"
16	
17		"github.com/go-git/go-git/v6"
18		"github.com/go-git/go-git/v6/plumbing"
19		"github.com/go-git/go-git/v6/plumbing/object"
20		"github.com/go-git/go-git/v6/plumbing/storer"
21	)
22	
23	type discoveryOptions struct {
24		since string
25		head  string
26	}
27	
28	type discoveredCheckpoint struct {
29		ID      checkpointID.CheckpointID
30		Commits []discoveredCommit
31	}
32	
33	type discoveredCommit struct {
34		Hash     plumbing.Hash
35		ShortSHA string
36		Date     time.Time
37	}
38	
39	type historyTip struct {
40		name string
41		hash plumbing.Hash
42	}
43	
44	type discoveryScope struct {
45		excluded  map[plumbing.Hash]bool
46		sinceHash plumbing.Hash
47		hasSince  bool
48	}
49	
50	func discoverCheckpointHistory(ctx context.Context, repo *git.Repository, opts discoveryOptions) ([]discoveredCheckpoint, error) {
51		checkpoints, _, err := discoverCheckpointHistoryWithSkippedOrphans(ctx, repo, opts)
52		return checkpoints, err
53	}
54	
55	func discoverCheckpointHistoryWithSkippedOrphans(ctx context.Context, repo *git.Repository, opts discoveryOptions) ([]discoveredCheckpoint, int, error) {
56		checkpoints, checkpointIndexes, err := discoverTrailerCheckpointHistory(ctx, repo, opts)
57		if err != nil {
58			return nil, 0, err
59		}
60	
61		v2OrphansSkipped, err := addV2OrphanCheckpoints(ctx, repo, opts, checkpointIndexes, &checkpoints)
62		if err != nil {
63			return nil, 0, err
64		}
65	
66		sortDiscoveredCheckpoints(checkpoints)
67		return checkpoints, v2OrphansSkipped, nil
68	}
69	
70	func discoverTrailerCheckpointHistory(ctx context.Context, repo *git.Repository, opts discoveryOptions) ([]discoveredCheckpoint, map[string]int, error) {
71		scope, err := newDiscoveryScope(ctx, repo, opts.since)
72		if err != nil {
73			return nil, nil, err
74		}
75	
76		tips, err := historyTips(ctx, repo, opts.head, scope)
77		if err != nil {
78			return nil, nil, err
79		}
80	
81		seenCommits := make(map[plumbing.Hash]bool)
82		checkpointIndexes := make(map[string]int)
83		checkpoints := make([]discoveredCheckpoint, 0)
84	
85		for _, tip := range tips {
86			if err := scanTip(ctx, repo, tip, scope.excluded, seenCommits, checkpointIndexes, &checkpoints); err != nil {
87				return nil, nil, err
88			}
89		}
90	
91		return checkpoints, checkpointIndexes, nil
92	}
93	
94	func newDiscoveryScope(ctx context.Context, repo *git.Repository, since string) (discoveryScope, error) {
95		if since == "" {
96			return discoveryScope{excluded: make(map[plumbing.Hash]bool)}, nil
97		}
98	
99		sinceHash, err := resolveRevision(repo, since)
100		if err != nil {
101			return discoveryScope{}, fmt.Errorf("resolve --since %q: %w", since, err)
102		}
103		excluded, err := reachableCommits(ctx, repo, sinceHash)
104		if err != nil {
105			return discoveryScope{}, err
106		}
107		return discoveryScope{
108			excluded:  excluded,
109			sinceHash: sinceHash,
110			hasSince:  true,
111		}, nil
112	}
113	
114	func historyTips(ctx context.Context, repo *git.Repository, head string, scope discoveryScope) ([]historyTip, error) {
115		if head != "" {
116			hash, err := resolveRevision(repo, head)
117			if err != nil {
118				return nil, fmt.Errorf("resolve --head %q: %w", head, err)
119			}
120			if err := requireTipContainsSince(ctx, repo, hash, head, scope); err != nil {
121				return nil, err
122			}
123			return []historyTip{{name: head, hash: hash}}, nil
124		}
125	
126		iter, err := repo.References()
127		if err != nil {
128			return nil, fmt.Errorf("list refs: %w", err)
129		}
130		defer iter.Close()
131	
132		var tips []historyTip
133		seenHashes := make(map[plumbing.Hash]bool)
134		err = iter.ForEach(func(ref *plumbing.Reference) error {
135			if !isHistoryRef(ref) {
136				return nil
137			}
138	
139			hash := ref.Hash()
140			if seenHashes[hash] {
141				return nil
142			}
143			include, includeErr := tipContainsSince(ctx, repo, hash, scope)
144			if includeErr != nil {
145				return fmt.Errorf("check whether %s contains --since: %w", ref.Name(), includeErr)
146			}
147			if !include {
148				return nil
149			}
150			seenHashes[hash] = true
151			tips = append(tips, historyTip{name: ref.Name().String(), hash: hash})
152			return nil
153		})
154		if err != nil {
155			return nil, fmt.Errorf("iterate refs: %w", err)
156		}
157	
158		if len(tips) == 0 {
159			headRef, headErr := repo.Head()
160			if headErr != nil {
161				return nil, fmt.Errorf("find HEAD: %w", headErr)
162			}
163			include, includeErr := tipContainsSince(ctx, repo, headRef.Hash(), scope)
164			if includeErr != nil {
165				return nil, fmt.Errorf("check whether HEAD contains --since: %w", includeErr)
166			}
167			if include {
168				tips = append(tips, historyTip{name: headRef.Name().String(), hash: headRef.Hash()})
169			}
170		}
171	
172		sort.Slice(tips, func(i, j int) bool {
173			return tips[i].name < tips[j].name
174		})
175		return tips, nil
176	}
177	
178	func requireTipContainsSince(ctx context.Context, repo *git.Repository, tipHash plumbing.Hash, tipName string, scope discoveryScope) error {
179		contains, err := tipContainsSince(ctx, repo, tipHash, scope)
180		if err != nil {
181			return fmt.Errorf("check whether --head %q contains --since: %w", tipName, err)
182		}
183		if !contains {
184			return fmt.Errorf("%s is not an ancestor of --head %q", scope.sinceHash, tipName)
185		}
186		return nil
187	}
188	
189	func tipContainsSince(ctx context.Context, repo *git.Repository, tipHash plumbing.Hash, scope discoveryScope) (bool, error) {
190		if !scope.hasSince {
191			return true, nil
192		}
193		return commitReachableFrom(ctx, repo, tipHash, scope.sinceHash)
194	}
195	
196	func isHistoryRef(ref *plumbing.Reference) bool {
197		if ref.Type() != plumbing.HashReference {
198			return false
199		}
200		name := ref.Name()
201		if !name.IsBranch() && !name.IsRemote() {
202			return false
203		}
204		if isInternalHistoryRefName(name) {
205			return false
206		}
207		return !strings.HasSuffix(name.String(), "/HEAD")
208	}
209	
210	func isInternalHistoryRefName(name plumbing.ReferenceName) bool {
211		if name == plumbing.NewBranchReferenceName(paths.MetadataBranchName) ||
212			name == plumbing.NewBranchReferenceName(paths.TrailsBranchName) {
213			return true
214		}
215	
216		remotePrefix := "refs/remotes/"
217		nameString := name.String()
218		if !strings.HasPrefix(nameString, remotePrefix) {
219			return false
220		}
221		remoteAndBranch := strings.TrimPrefix(nameString, remotePrefix)
222		_, branchName, ok := strings.Cut(remoteAndBranch, "/")
223		if !ok {
224			return false
225		}
226		return branchName == paths.MetadataBranchName || branchName == paths.TrailsBranchName
227	}
228	
229	func resolveRevision(repo *git.Repository, revision string) (plumbing.Hash, error) {
230		if isShortHexRevision(revision) {
231			if err := rejectAmbiguousCommitPrefix(repo, revision); err != nil {
232				return plumbing.ZeroHash, err
233			}
234		}
235	
236		hash, err := repo.ResolveRevision(plumbing.Revision(revision))
237		if err != nil {
238			return plumbing.ZeroHash, err //nolint:wrapcheck // callers add flag-specific context
239		}
240		if hash == nil {
241			return plumbing.ZeroHash, fmt.Errorf("revision %q resolved to no commit", revision)
242		}
243		return *hash, nil
244	}
245	
246	func isShortHexRevision(revision string) bool {
247		if revision == "" || len(revision) >= len(plumbing.ZeroHash.String()) {
248			return false
249		}
250		for _, r := range revision {
251			switch {
252			case r >= '0' && r <= '9':
253			case r >= 'a' && r <= 'f':
254			case r >= 'A' && r <= 'F':
255			default:
256				return false
257			}
258		}
259		return true
260	}
261	
262	func rejectAmbiguousCommitPrefix(repo *git.Repository, revision string) error {
263		prefix := strings.ToLower(revision)
264		iter, err := repo.CommitObjects()
265		if err != nil {
266			return fmt.Errorf("list commit objects for revision %q: %w", revision, err)
267		}
268		defer iter.Close()
269	
270		var matches []plumbing.Hash
271		err = iter.ForEach(func(commit *object.Commit) error {
272			if strings.HasPrefix(commit.Hash.String(), prefix) {
273				matches = append(matches, commit.Hash)
274				if len(matches) == 2 {
275					return storer.ErrStop
276				}
277			}
278			return nil
279		})
280		if err != nil && !errors.Is(err, storer.ErrStop) {
281			return fmt.Errorf("scan commit objects for revision %q: %w", revision, err)
282		}
283		if len(matches) < 2 {
284			return nil
285		}
286		sort.Slice(matches, func(i, j int) bool {
287			return matches[i].String() < matches[j].String()
288		})
289		return fmt.Errorf("ambiguous revision %q matches commit prefixes %s and %s", revision, matches[0], matches[1])
290	}
291	
292	func reachableCommits(ctx context.Context, repo *git.Repository, from plumbing.Hash) (map[plumbing.Hash]bool, error) {
293		iter, err := repo.Log(&git.LogOptions{From: from, Order: git.LogOrderCommitterTime})
294		if err != nil {
295			return nil, fmt.Errorf("get log from %s: %w", from, err)
296		}
297		defer iter.Close()
298	
299		commits := make(map[plumbing.Hash]bool)
300		err = iter.ForEach(func(commit *object.Commit) error {
301			if err := ctx.Err(); err != nil {
302				return fmt.Errorf("context canceled while excluding commits: %w", err)
303			}
304			commits[commit.Hash] = true
305			return nil
306		})
307		if err != nil {
308			return nil, fmt.Errorf("iterate commits reachable from %s: %w", from, err)
309		}
310		return commits, nil
311	}
312	
313	func commitReachableFrom(ctx context.Context, repo *git.Repository, from, target plumbing.Hash) (bool, error) {
314		iter, err := repo.Log(&git.LogOptions{From: from, Order: git.LogOrderCommitterTime})
315		if err != nil {
316			return false, fmt.Errorf("get log from %s: %w", from, err)
317		}
318		defer iter.Close()
319	
320		found := false
321		err = iter.ForEach(func(commit *object.Commit) error {
322			if err := ctx.Err(); err != nil {
323				return fmt.Errorf("context canceled while checking ancestry: %w", err)
324			}
325			if commit.Hash == target {
326				found = true
327				return storer.ErrStop
328			}
329			return nil
330		})
331		if errors.Is(err, storer.ErrStop) {
332			return true, nil
333		}
334		if err != nil {
335			return false, fmt.Errorf("iterate commits from %s: %w", from, err)
336		}
337		return found, nil
338	}
339	
340	func scanTip(ctx context.Context, repo *git.Repository, tip historyTip, excluded, seenCommits map[plumbing.Hash]bool, checkpointIndexes map[string]int, checkpoints *[]discoveredCheckpoint) error {
341		iter, err := repo.Log(&git.LogOptions{From: tip.hash, Order: git.LogOrderCommitterTime})
342		if err != nil {
343			return fmt.Errorf("get log from %s: %w", tip.name, err)
344		}
345		defer iter.Close()
346	
347		err = iter.ForEach(func(commit *object.Commit) error {
348			if err := ctx.Err(); err != nil {
349				return fmt.Errorf("context canceled while scanning commits: %w", err)
350			}
351			if excluded[commit.Hash] || seenCommits[commit.Hash] {
352				return nil
353			}
354			seenCommits[commit.Hash] = true
355			addCheckpointCommit(commit, checkpointIndexes, checkpoints)
356			return nil
357		})
358		if err != nil {
359			return fmt.Errorf("iterate commits from %s: %w", tip.name, err)
360		}
361		return nil
362	}
363	
364	func addV2OrphanCheckpoints(ctx context.Context, repo *git.Repository, opts discoveryOptions, checkpointIndexes map[string]int, checkpoints *[]discoveredCheckpoint) (int, error) {
365		v2CheckpointIDs, err := listV2MainCheckpointIDs(ctx, repo)
366		if err != nil {
367			return 0, err
368		}
369		if len(v2CheckpointIDs) == 0 {
370			return 0, nil
371		}
372	
373		if hasCommitScope(opts) {
374			_, unscopedIndexes, err := discoverTrailerCheckpointHistory(ctx, repo, discoveryOptions{})
375			if err != nil {
376				return 0, err
377			}
378	
379			return countMissingCheckpointIDs(v2CheckpointIDs, unscopedIndexes), nil
380		}
381	
382		for _, cpID := range v2CheckpointIDs {
383			key := cpID.String()
384			if _, exists := checkpointIndexes[key]; exists {
385				continue
386			}
387			checkpointIndexes[key] = len(*checkpoints)
388			*checkpoints = append(*checkpoints, discoveredCheckpoint{ID: cpID})
389		}
390	
391		return 0, nil
392	}
393	
394	func hasCommitScope(opts discoveryOptions) bool {
395		return opts.since != "" || opts.head != ""
396	}
397	
398	func countMissingCheckpointIDs(ids []checkpointID.CheckpointID, indexes map[string]int) int {
399		missing := 0
400		for _, cpID := range ids {
401			if _, exists := indexes[cpID.String()]; !exists {
402				missing++
403			}
404		}
405		return missing
406	}
407	
408	func listV2MainCheckpointIDs(ctx context.Context, repo *git.Repository) ([]checkpointID.CheckpointID, error) {
409		v2Store := checkpoint.NewV2GitStore(repo)
410		_, rootTreeHash, err := v2Store.GetRefState(plumbing.ReferenceName(paths.V2MainRefName))
411		if errors.Is(err, plumbing.ErrReferenceNotFound) {
412			return nil, nil
413		}
414		if err != nil {
415			return nil, fmt.Errorf("read %s ref state: %w", paths.V2MainRefName, err)
416		}
417	
418		rootTree, err := repo.TreeObject(rootTreeHash)
419		if err != nil {
420			return nil, fmt.Errorf("read %s root tree: %w", paths.V2MainRefName, err)
421		}
422	
423		var ids []checkpointID.CheckpointID
424		err = checkpoint.WalkCheckpointShards(ctx, repo, rootTree, func(cpID checkpointID.CheckpointID, cpTreeHash plumbing.Hash) error {
425			cpTree, cpTreeErr := repo.TreeObject(cpTreeHash)
426			if cpTreeErr != nil {
427				return fmt.Errorf("read v2 checkpoint %s tree: %w", cpID, cpTreeErr)
428			}
429			if _, fileErr := cpTree.File(paths.MetadataFileName); fileErr == nil {
430				ids = append(ids, cpID)
431			}
432			return nil
433		})
434		if err != nil {
435			return nil, fmt.Errorf("walk %s checkpoints: %w", paths.V2MainRefName, err)
436		}
437	
438		sort.Slice(ids, func(i, j int) bool {
439			return ids[i].String() < ids[j].String()
440		})
441		return ids, nil
442	}
443	
444	func addCheckpointCommit(commit *object.Commit, checkpointIndexes map[string]int, checkpoints *[]discoveredCheckpoint) {
445		ids := trailers.ParseAllCheckpoints(commit.Message)
446		if len(ids) == 0 {
447			return
448		}
449	
450		discovered := discoveredCommit{
451			Hash:     commit.Hash,
452			ShortSHA: shortHash(commit.Hash),
453			Date:     commit.Committer.When,
454		}
455	
456		for _, id := range ids {
457			key := id.String()
458			index, ok := checkpointIndexes[key]
459			if !ok {
460				index = len(*checkpoints)
461				checkpointIndexes[key] = index
462				*checkpoints = append(*checkpoints, discoveredCheckpoint{ID: id})
463			}
464			(*checkpoints)[index].Commits = append((*checkpoints)[index].Commits, discovered)
465		}
466	}
467	
468	func sortDiscoveredCheckpoints(checkpoints []discoveredCheckpoint) {
469		sort.Slice(checkpoints, func(i, j int) bool {
470			return checkpoints[i].ID.String() < checkpoints[j].ID.String()
471		})
472		for i := range checkpoints {
473			sort.Slice(checkpoints[i].Commits, func(j, k int) bool {
474				left := checkpoints[i].Commits[j]
475				right := checkpoints[i].Commits[k]
476				if !left.Date.Equal(right.Date) {
477					return left.Date.After(right.Date)
478				}
479				return left.Hash.String() < right.Hash.String()
480			})
481		}
482	}
483	
484	func writeCheckpointList(w io.Writer, checkpoints []discoveredCheckpoint) {
485		for _, checkpoint := range checkpoints {
486			fmt.Fprint(w, checkpoint.ID)
487			if len(checkpoint.Commits) == 0 {
488				fmt.Fprint(w, " (orphan)")
489			}
490			for _, commit := range checkpoint.Commits {
491				fmt.Fprintf(w, " %s", commit.ShortSHA)
492			}
493			fmt.Fprintln(w)
494		}
495	}
496	
497	func writeDiscoveryWarnings(w io.Writer, v2OrphansSkipped int) {
498		if v2OrphansSkipped == 0 {
499			return
500		}
501		fmt.Fprintf(w, "warning: %d v2 orphans skipped; re-run without --since/--head to include them\n", v2OrphansSkipped)
502	}
503	
504	func shortHash(hash plumbing.Hash) string {
505		full := hash.String()
506		if len(full) <= checkpointID.ShortIDLength {
507			return full
508		}
509		return full[:checkpointID.ShortIDLength]
510	}
